public struct FfiConverterTypeSteamSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = SteamSession

    public static func lift(_ handle: UInt64) throws -> SteamSession {
        return SteamSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: SteamSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SteamSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SteamSession, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


